dot.example:
// Is the target in front of the player? (the world faces +Y)
const forward = player.rotation.rotateVector(new kcds.math.Vector3(0, 1, 0));
const inFront = forward.dot(target.position.clone().sub(player.position)) > 0;

dot.exampleCs:
// Is the target in front of the player? (the world faces +Y)
var forward = player.Rotation.RotateVector(new Vector3(0, 1, 0));
var inFront = forward.Dot(target.Position.Clone().Sub(player.Position)) > 0;

